 const filterButtons = Array.from(document.querySelectorAll("[data-filter]"));
 const productCards = Array.from(document.querySelectorAll(".product-card"));
 const countdownNode = document.querySelector("[data-countdown]");
 const statusMessage = document.querySelector("[data-status-message]");
 const addToBagButtons = Array.from(document.querySelectorAll("[data-add-to-bag]"));
 const membershipForm = document.querySelector("[data-membership-form]");

 const announce = (message) => {
   if (statusMessage) {
     statusMessage.textContent = message;
   }
 };

 filterButtons.forEach((button) => {
   button.addEventListener("click", () => {
     const { filter } = button.dataset;

     filterButtons.forEach((chip) => {
       const isActive = chip === button;
       chip.classList.toggle("is-active", isActive);
       chip.setAttribute("aria-pressed", String(isActive));
     });

     productCards.forEach((card) => {
       const matches = filter === "all" || card.dataset.category === filter;
       card.classList.toggle("is-hidden", !matches);
       card.hidden = !matches;
     });
   });
 });

 addToBagButtons.forEach((button) => {
   button.addEventListener("click", () => {
     announce(`${button.getAttribute("aria-label")?.replace("Add to bag: ", "")} added to bag.`);
   });
 });

 if (membershipForm instanceof HTMLFormElement) {
   membershipForm.addEventListener("submit", (event) => {
     event.preventDefault();

     if (!membershipForm.reportValidity()) {
       return;
     }

     const emailInput = membershipForm.elements.namedItem("email");

     if (emailInput instanceof HTMLInputElement) {
       announce(`Thanks for joining Northstar+ with ${emailInput.value}.`);
       membershipForm.reset();
       emailInput.focus();
     }
   });
 }

 if (countdownNode) {
   const targetTime = Date.now() + (18 * 60 * 60 + 12 * 60 + 45) * 1000;

   const updateCountdown = () => {
     const remainingMs = Math.max(0, targetTime - Date.now());
     const totalSeconds = Math.floor(remainingMs / 1000);
     const hours = String(Math.floor(totalSeconds / 3600)).padStart(2, "0");
     const minutes = String(Math.floor((totalSeconds % 3600) / 60)).padStart(2, "0");
     const seconds = String(totalSeconds % 60).padStart(2, "0");

     countdownNode.textContent = `${hours}:${minutes}:${seconds}`;
   };

   updateCountdown();
   window.setInterval(updateCountdown, 1000);
 }

